CREATE DATABASE IF NOT EXISTS aarogya_care;
USE aarogya_care;
CREATE TABLE departments (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, code VARCHAR(10) NOT NULL UNIQUE, consultation_fee DECIMAL(10,2) NOT NULL DEFAULT 500, status VARCHAR(20) DEFAULT 'Active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL, status VARCHAR(20) DEFAULT 'Active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE patients (id INT AUTO_INCREMENT PRIMARY KEY, patient_id VARCHAR(20) NOT NULL UNIQUE, user_id INT, full_name VARCHAR(100) NOT NULL, guardian_name VARCHAR(100), dob DATE, gender VARCHAR(20), mobile VARCHAR(15) NOT NULL, email VARCHAR(150), address VARCHAR(255), city VARCHAR(100), state VARCHAR(100), pin_code VARCHAR(10), emergency_contact VARCHAR(15), blood_group VARCHAR(10), status VARCHAR(20) DEFAULT 'Active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE doctors (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT, name VARCHAR(100) NOT NULL, qualification VARCHAR(100), department_id INT, experience VARCHAR(50), consultation_fee DECIMAL(10,2) DEFAULT 500, status VARCHAR(20) DEFAULT 'Available', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(department_id) REFERENCES departments(id));
CREATE TABLE appointments (id INT AUTO_INCREMENT PRIMARY KEY, appointment_id VARCHAR(20) NOT NULL UNIQUE, patient_id INT NOT NULL, doctor_id INT NOT NULL, department_id INT NOT NULL, appointment_date DATE NOT NULL, appointment_time VARCHAR(10) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'Scheduled', priority TINYINT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(patient_id) REFERENCES patients(id), FOREIGN KEY(doctor_id) REFERENCES doctors(id), FOREIGN KEY(department_id) REFERENCES departments(id), UNIQUE KEY uq_slot (doctor_id,appointment_date,appointment_time));
CREATE TABLE tokens (id INT AUTO_INCREMENT PRIMARY KEY, token_number VARCHAR(20) NOT NULL UNIQUE, appointment_id INT NOT NULL, department_id INT NOT NULL, status VARCHAR(20) DEFAULT 'Waiting', called_at TIMESTAMP NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(appointment_id) REFERENCES appointments(id), FOREIGN KEY(department_id) REFERENCES departments(id));
CREATE TABLE consultations (id INT AUTO_INCREMENT PRIMARY KEY, appointment_id INT NOT NULL, patient_id INT NOT NULL, doctor_id INT NOT NULL, symptoms TEXT, diagnosis TEXT, doctor_notes TEXT, follow_up_date DATE, status VARCHAR(20) DEFAULT 'In Progress', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(appointment_id) REFERENCES appointments(id), FOREIGN KEY(patient_id) REFERENCES patients(id), FOREIGN KEY(doctor_id) REFERENCES doctors(id));
CREATE TABLE prescriptions (id INT AUTO_INCREMENT PRIMARY KEY, consultation_id INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(consultation_id) REFERENCES consultations(id));
CREATE TABLE prescription_items (id INT AUTO_INCREMENT PRIMARY KEY, prescription_id INT NOT NULL, medicine_name VARCHAR(150) NOT NULL, dosage VARCHAR(50), frequency VARCHAR(50), duration VARCHAR(50), instructions VARCHAR(255), FOREIGN KEY(prescription_id) REFERENCES prescriptions(id));
CREATE TABLE notifications (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, message VARCHAR(255) NOT NULL, is_read TINYINT DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE payments (id INT AUTO_INCREMENT PRIMARY KEY, appointment_id INT NOT NULL, amount DECIMAL(10,2) NOT NULL, status VARCHAR(20) DEFAULT 'Pending', payment_method VARCHAR(30), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(appointment_id) REFERENCES appointments(id));
CREATE TABLE audit_logs (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT, action VARCHAR(150) NOT NULL, description VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));
